import{at as e,it as t,n,vt as r}from"./chunks/framework.CsjHfu6k.js";var i=JSON.parse(`{"title":"2024.10.10 Magisk v28.0","description":"","frontmatter":{},"headers":[],"relativePath":"releases/28000.md","filePath":"releases/28000.md","lastUpdated":1792939073000}`),a={name:`releases/28000.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="_2024-10-10-magisk-v28-0" tabindex="-1">2024.10.10 Magisk v28.0 <a class="header-anchor" href="#_2024-10-10-magisk-v28-0" aria-label="Permalink to “2024.10.10 Magisk v28.0”">​</a></h1><ul><li>[General] 支持 16K 页面大小</li><li>[General] 添加对 RISC-V 的基本支持（发布版本中未构建）</li><li>[General] 使用精简 libc 构建静态可执行文件（<code>magiskinit</code> 和 <code>magiskboot</code>），以减小体积</li><li>[Core] 移除 magic mount 不需要的镜像</li><li>[Core] 更新启动映像检测逻辑，以支持更多设备</li><li>[MagiskInit] 重写将 <code>magiskinit</code> 作为 <code>init</code> 注入的 2SI 逻辑</li><li>[MagiskInit] 更新预初始化分区检测</li><li>[Zygisk] 更新内部 JNI 挂钩实现</li><li>[MagiskPolicy] 修补后保留 sepolicy 配置标志</li><li>[MagiskPolicy] 优化修补规则，减少注入的新规则数量</li><li>[DenyList] 支持在禁用 Zygisk 时仍强制执行拒绝列表</li><li>[Resetprop] 改进实现，以绕过若干属性修改检测</li><li>[Resetprop] 更新以正确处理属性覆盖（property overlays）</li><li>[App] 大规模内部代码重构</li><li>[App] 支持修补大于 8GiB 的三星固件映像</li><li>[App] 在 Android 14 上使用用户发起的作业代替前台服务</li><li>[App] 支持 Android 13+ 内置的按应用语言偏好设置</li><li>[App] 添加 <code>action.sh</code> 支持，允许模块定义从 UI 触发的操作</li><li>[MagiskBoot] 支持在不进行解压缩的情况下拆分内核映像</li><li>[MagiskBoot] 正确支持 vendor boot 映像</li><li>[MagiskBoot] 从内核映像中禁用三星 PROCA</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[General] Support 16k page size</li><li>[General] Add basic support for RISC-V (not built in releases)</li><li>[General] Use a minimal libc to build static executables (<code>magiskinit</code> and <code>magiskboot</code>) for smaller sizes</li><li>[Core] Remove unnecessary mirror for magic mount</li><li>[Core] Update boot image detection logic to support more devices</li><li>[MagiskInit] Rewrite 2SI logic for injecting <code>magiskinit</code> as <code>init</code></li><li>[MagiskInit] Update preinit partition detection</li><li>[Zygisk] Update internal JNI hooking implementation</li><li>[MagiskPolicy] Preserve sepolicy config flag after patching</li><li>[MagiskPolicy] Optimize patching rules to reduce the amount of new rules being injected</li><li>[DenyList] Support enforcing denylist when Zygisk is disabled</li><li>[Resetprop] Improve implementation to workaround several property modification detections</li><li>[Resetprop] Update to properly work with property overlays</li><li>[App] Major internal code refactoring</li><li>[App] Support patching Samsung firmware with images larger than 8GiB</li><li>[App] Use user-initiated job instead of foreground services on Android 14</li><li>[App] Support Android 13+ built-in per-app language preferences</li><li>[App] Add <code>action.sh</code> support to allow modules to define an action triggered from UI</li><li>[MagiskBoot] Support spliting kernel images without decompression</li><li>[MagiskBoot] Properly support vendor boot images</li><li>[MagiskBoot] Disable Samsung PROCA from kernel image</li></ul></details><p><strong>完整更新日志： <a href="/MagiskChineseDocument/changes.html">这里</a></strong></p>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};